/**
 * UI controller. Everything stateful lives in Python; this file renders it and
 * forwards intent over the pywebview bridge.
 *
 * Note on the orb's amplitude: the assistant's voice is generated by Windows
 * SAPI in the Python process, which — exactly like the browser's
 * SpeechSynthesis in the original Victoria app — exposes no audio stream to
 * analyse. So "speaking" drives a synthesised envelope, the same fallback the
 * original used for its local-voice path.
 */
(function () {
  /* Say something when the UI dies.
   *
   * index.html carries the whole layout as static markup — rail, tabs, orb
   * canvas, composer — so if this script stops running the window still LOOKS
   * like the app while nothing responds and Python never hears from the page.
   * That is indistinguishable from a hang, and reports it as one.
   *
   * Installed before anything else here can throw, and deliberately using no
   * helper defined below it (const declarations further down are still in their
   * temporal dead zone while this runs).
   */
  function fatal(message) {
    try {
      var bar = document.getElementById("fatalBar");
      if (!bar) {
        bar = document.createElement("div");
        bar.id = "fatalBar";
        bar.className = "fatal-bar";
        (document.body || document.documentElement).appendChild(bar);
      }
      bar.textContent = "The interface failed to start: " + message +
        " — please reopen Jarvis, and send the log (Settings → Open data folder).";
      var bridge = window.pywebview && window.pywebview.api;
      if (bridge && bridge.note) bridge.note("FATAL in UI: " + message);
    } catch (err) {
      /* nothing left to try */
    }
  }

  window.addEventListener("error", (e) => {
    fatal((e && e.message) || "unknown error");
  });
  window.addEventListener("unhandledrejection", (e) => {
    fatal("unhandled promise rejection: " + ((e && e.reason && e.reason.message) || e.reason || "unknown"));
  });

  const $ = (id) => document.getElementById(id);
  const api = () => window.pywebview && window.pywebview.api;

  /** The drawing helpers live in separate script files; a build or extraction
   *  that drops one of them must fail loudly, not leave a dead window. */
  function requireGlobal(name) {
    if (typeof window[name] !== "function") {
      throw new Error(name + " is missing (a script file failed to load)");
    }
    return window[name];
  }

  let state = null;
  let turns = [];
  let busy = false;
  let speaking = false;
  let listening = false;
  let muted = false;

  // ---------------------------------------------------------------- visuals

  function orbState() {
    if (listening) return "listening";
    if (busy) return "thinking";
    if (speaking) return "speaking";
    return "idle";
  }

  // Real loudness of the neural voice when it's playing in the page; a
  // synthesised envelope only on the offline-voice fallback.
  const amplitude = () => (window.JarvisVoice ? window.JarvisVoice.amplitude() : 0);

  const mountOrb = requireGlobal("mountOrb");
  const mountWave = requireGlobal("mountWave");
  const hero = mountOrb($("heroOrb"), { getAmplitude: amplitude });
  const mini = mountOrb($("miniOrbCanvas"), { getAmplitude: amplitude });
  const wave = mountWave($("wave"), { height: 40, getAmplitude: amplitude });

  function syncVisualState() {
    const s = orbState();
    hero.setState(s);
    mini.setState(s);
    wave.setState(s);
  }

  // Filled in by wire(), reported to the log once boot() has resolved.
  let capabilityNote = "";

  /** Write one line into the app's log file. Never throws, never blocks. */
  function note(message) {
    try {
      const bridge = api();
      if (bridge && bridge.note) bridge.note(message);
    } catch (err) {
      /* the demo build has no such method, and the window may be closing */
    }
  }

  let toastTimer = 0;
  function toast(message) {
    const el = $("toast");
    el.textContent = message;
    el.hidden = false;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => { el.hidden = true; }, 3200);
  }

  // ---------------------------------------------------------------- helpers

  function fmtSize(bytes) {
    const units = ["B", "KB", "MB", "GB", "TB"];
    let n = bytes || 0;
    let i = 0;
    while (n >= 1024 && i < units.length - 1) { n /= 1024; i++; }
    return (i === 0 ? n.toFixed(0) : n.toFixed(1)) + " " + units[i];
  }

  function fmtWhen(ts) {
    if (!ts) return "";
    const delta = Date.now() / 1000 - ts;
    if (delta < 60) return "just now";
    if (delta < 3600) return Math.floor(delta / 60) + "m ago";
    if (delta < 86400) return Math.floor(delta / 3600) + "h ago";
    return new Date(ts * 1000).toLocaleDateString();
  }

  function el(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  // ---------------------------------------------------------------- rendering

  function renderState(next) {
    if (!next) return;
    state = next;
    const b = state.branding || {};
    // The rail is narrow, so it wears the short name; the window title carries
    // the full product name.
    $("brandName").textContent = b.short_name || b.product_name || "Jarvis";
    $("brandSub").textContent = b.subtitle || "";
    $("chatTitle").textContent = b.assistant_name || b.short_name || "Jarvis";
    document.title = (b.product_name || "Jarvis") + " — " + (b.subtitle || "");
    if (b.accent) {
      document.documentElement.style.setProperty("--accent", b.accent);
      if (b.accent_dim) document.documentElement.style.setProperty("--accent-dim", b.accent_dim);
    }

    const cfg = state.config || {};
    $("folderPath").textContent = cfg.watch_folder || "No folder selected";

    const watching = state.watch && state.watch.running;
    const badge = $("watchBadge");
    badge.textContent = watching ? "watching" : "idle";
    badge.classList.toggle("is-live", !!watching);
    $("toggleWatch").textContent = watching ? "Pause" : "Start";

    const ai = state.ai || {};

    const st = state.stats || { files: 0, bytes: 0, filed: 0 };
    const stats = $("stats");
    stats.innerHTML = "";
    [
      [st.files, "indexed"],
      [st.filed, "filed"],
      [fmtSize(st.bytes), "size"],
    ].forEach(([value, label]) => {
      const card = el("div", "stat");
      card.appendChild(el("div", "stat-value", String(value)));
      card.appendChild(el("div", "stat-label", label));
      stats.appendChild(card);
    });

    // Settings controls mirror config exactly, so what's on screen is always
    // what the background service is actually doing.
    $("autoOrganize").checked = !!cfg.auto_organize;
    $("recursive").checked = !!cfg.recursive;
    $("indexExisting").checked = !!cfg.index_existing;
    $("speakReplies").checked = !!cfg.speak_replies;
    muted = !cfg.speak_replies;
    $("muteBtn").classList.toggle("is-off", muted);
    $("confidence").value = cfg.min_confidence != null ? cfg.min_confidence : 0.55;
    $("confidenceValue").textContent = Number($("confidence").value).toFixed(2);
    if (document.activeElement !== $("categories")) {
      $("categories").value = (state.categories || []).join(", ");
    }
    const voice = state.voice || {};
    const picker = $("voicePicker");
    if (picker.options.length !== (voice.voices || []).length) {
      picker.innerHTML = "";
      (voice.voices || []).forEach((v) => {
        const option = document.createElement("option");
        option.value = v.id;
        option.textContent = v.label;
        picker.appendChild(option);
      });
    }
    picker.value = voice.current || "";
    picker.disabled = !voice.natural_enabled;
    $("naturalVoice").checked = !!voice.natural_enabled;
    $("voiceHint").textContent = voice.natural_enabled
      ? (voice.natural_available
          ? "Natural online voice. Falls back to this PC's own voice if the connection drops."
          : "Natural voice unavailable in this build — using " + (voice.offline_voice || "the system voice") + ".")
      : "Using this PC's built-in voice: " + (voice.offline_voice || "none") + ".";

    $("keyStatus").textContent = state.has_key
      ? "Key saved and encrypted for this Windows user (" + ai.provider + ")."
      : "No key set — running on offline rules.";
    $("keyStatus").className = "hint " + (state.has_key ? "is-ok" : "");
    $("versionNote").textContent =
      "v" + state.version + (state.tts ? " · voice ready" : " · no voice engine") +
      "\n" + state.data_dir;

    // Guarded by its own flag, not by a child count: with every ask in the
    // header menu the hero grid is legitimately empty, and a count check would
    // rebuild the menu on every state poll — under the user's cursor.
    if (!suggestionsRendered) renderSuggestions(b.suggestions || []);
  }

  /* How many asks get their own tile in the hero. All of them now live behind
     the bolt pill in the header instead, so the orb has the whole column —
     raise this if a future build wants headline tiles back. */
  const HERO_SUGGESTIONS = 0;
  let suggestionsRendered = false;

  function renderSuggestions(list) {
    suggestionsRendered = true;
    const box = $("suggestions");
    const menu = $("quickMenu");
    const pill = $("quickBtn");
    box.innerHTML = "";
    menu.innerHTML = "";

    list.slice(0, HERO_SUGGESTIONS).forEach((text) => {
      const btn = el("button", "suggestion", text);
      btn.type = "button";
      btn.addEventListener("click", () => send(text));
      box.appendChild(btn);
    });

    const overflow = list.slice(HERO_SUGGESTIONS);
    overflow.forEach((text) => {
      const item = el("button", "quick-item", text);
      item.type = "button";
      item.setAttribute("role", "menuitem");
      item.addEventListener("click", () => {
        closeQuickMenu();
        send(text);
      });
      menu.appendChild(item);
    });
    // Nothing left over means no menu to open — hide the pill rather than
    // offer an empty dropdown.
    pill.hidden = overflow.length === 0;
    if (pill.hidden) closeQuickMenu();
  }

  function closeQuickMenu() {
    $("quickMenu").hidden = true;
    $("quickBtn").classList.remove("is-open");
    $("quickBtn").setAttribute("aria-expanded", "false");
  }

  function toggleQuickMenu() {
    const menu = $("quickMenu");
    const open = menu.hidden;
    menu.hidden = !open;
    $("quickBtn").classList.toggle("is-open", open);
    $("quickBtn").setAttribute("aria-expanded", String(open));
  }

  function renderTurns() {
    const box = $("turns");
    box.hidden = turns.length === 0;
    $("hero").hidden = turns.length > 0;
    box.innerHTML = "";
    turns.forEach((turn) => {
      const wrap = el("div", "turn " + (turn.role === "user" ? "is-user" : "is-bot"));
      wrap.appendChild(el("div", "bubble", turn.text));
      if (turn.sources && turn.sources.length) {
        const row = el("div", "sources");
        turn.sources.slice(0, 6).forEach((src) => {
          const chip = el("button", "source", src.name || src.path);
          chip.type = "button";
          chip.title = src.path;
          chip.addEventListener("click", () => api().open_path(src.path));
          row.appendChild(chip);
        });
        wrap.appendChild(row);
      }
      box.appendChild(wrap);
    });
    if (busy) {
      const dots = el("div", "thinking");
      dots.appendChild(el("span"));
      dots.appendChild(el("span"));
      dots.appendChild(el("span"));
      box.appendChild(dots);
    }
    const scroll = $("scroll");
    scroll.scrollTop = scroll.scrollHeight;
  }

  function activityItem(record) {
    const kind = record.kind || "indexed";
    const name = record.name || (record.path || "").split(/[\\/]/).pop() || "(unknown)";
    const item = el("div", "item" + (record.error || kind === "error" ? " is-error" : ""));
    const top = el("div", "item-top");
    top.appendChild(el("div", "item-name", name));
    const label =
      kind === "moved" ? record.category || "filed"
      : kind === "deleted" ? "removed"
      : kind === "error" ? "error"
      : kind === "undone" ? "undone"
      : record.category || "indexed";
    top.appendChild(el("div", "item-cat", label));
    item.appendChild(top);

    const note = record.summary || record.note || record.error || "";
    if (note) item.appendChild(el("div", "item-note", note));

    const foot = el("div", "item-foot");
    foot.appendChild(el("div", "item-time", fmtWhen(record.ts)));
    if (record.path) {
      const open = el("button", "link-btn", "Open");
      open.type = "button";
      open.addEventListener("click", (e) => {
        e.stopPropagation();
        api().open_path(record.path);
      });
      foot.appendChild(open);
    }
    if (kind === "moved" && record.event_id && !record.undone) {
      const undo = el("button", "link-btn", "Undo");
      undo.type = "button";
      undo.addEventListener("click", async (e) => {
        e.stopPropagation();
        const result = await api().undo(record.event_id);
        toast(result.message || "Undone.");
        renderState(result.state);
        loadActivity();
      });
      foot.appendChild(undo);
    }
    item.appendChild(foot);
    if (record.path) {
      item.addEventListener("click", () => api().reveal_path(record.path));
    }
    return item;
  }

  async function loadActivity() {
    const events = await api().activity(60);
    const feed = $("feed");
    feed.innerHTML = "";
    if (!events.length) {
      feed.appendChild(el("div", "empty-note",
        "Nothing yet. Choose a folder and I'll start watching it."));
      return;
    }
    events.forEach((ev) => {
      feed.appendChild(activityItem({
        kind: ev.kind,
        path: ev.path,
        name: (ev.dest || ev.path || "").split(/[\\/]/).pop(),
        category: ev.category,
        note: ev.note,
        ts: ev.ts,
        event_id: ev.id,
        undone: ev.undone,
      }));
    });
  }

  // ---------------------------------------------------------------- asking

  async function send(question) {
    const q = (question || "").trim();
    if (!q || busy) return;
    $("input").value = "";
    $("send").disabled = true;
    turns.push({ role: "user", text: q });
    busy = true;
    syncVisualState();
    renderTurns();

    const history = turns.slice(-12).map((t) => ({ role: t.role, text: t.text }));
    try {
      const result = await api().ask(q, history);
      const answer = result.answer || "I couldn't answer that.";
      turns.push({ role: "assistant", text: answer, sources: result.sources || [] });
      if (!muted) window.JarvisVoice.speak(answer);
      if (result.refresh) {
        renderState(await api().state());
        loadActivity();
      }
    } catch (err) {
      turns.push({ role: "assistant", text: "Something went wrong: " + err });
    } finally {
      busy = false;
      syncVisualState();
      renderTurns();
      refreshStats();
    }
  }

  async function refreshStats() {
    try { renderState(await api().state()); } catch (e) { /* window closing */ }
  }

  // ---------------------------------------------------------------- events

  window.addEventListener("jarvis:activity", (e) => {
    const record = e.detail || {};
    const feed = $("feed");
    const note = feed.querySelector(".empty-note");
    if (note) note.remove();
    feed.prepend(activityItem(record));
    while (feed.childElementCount > 80) feed.lastElementChild.remove();
    if (record.moved) toast("Filed " + record.name + " → " + record.category);
  });

  // One source of truth for the "speaking" visual state, whichever engine is
  // actually producing the sound.
  window.JarvisVoice.onState = (next) => {
    speaking = next;
    syncVisualState();
  };

  window.addEventListener("jarvis:scan-done", (e) => {
    refreshStats();
    if (e.detail && e.detail.indexed != null) {
      toast("Finished: " + e.detail.indexed + " file(s) processed.");
    }
  });

  // ---------------------------------------------------------------- wiring

  function wire() {
    document.querySelectorAll(".tab").forEach((tab) => {
      tab.addEventListener("click", () => {
        document.querySelectorAll(".tab").forEach((t) => t.classList.remove("is-active"));
        document.querySelectorAll(".panel").forEach((p) => p.classList.remove("is-active"));
        tab.classList.add("is-active");
        document.querySelector('.panel[data-panel="' + tab.dataset.panel + '"]')
          .classList.add("is-active");
      });
    });

    $("composer").addEventListener("submit", (e) => {
      e.preventDefault();
      send($("input").value);
    });
    $("input").addEventListener("input", () => {
      $("send").disabled = !$("input").value.trim() || busy;
    });

    // Both orbs do the same thing, the way they do in the Toast build: tap to
    // dictate where the renderer provides speech recognition, otherwise tap to
    // shut the voice up mid-answer. The big hero orb used to be wired ONLY in
    // the no-recognition case, so on a machine that HAS recognition the hint
    // said "tap the orb" and tapping it did nothing at all.
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    let recognition = null;
    let handled = false;

    if (SR) {
      recognition = new SR();
      recognition.continuous = false;
      recognition.interimResults = false;
      recognition.lang = navigator.language || "en-US";
      recognition.onresult = (e) => {
        // Guard carried over from the Victoria build: some engines fire this
        // repeatedly for one utterance despite interimResults=false, which
        // would submit the same question several times.
        if (handled) return;
        const last = e.results[e.results.length - 1];
        if (!last || !last.isFinal) return;
        handled = true;
        listening = false;
        syncVisualState();
        recognition.stop();
        send(last[0].transcript);
      };
      // Say why nothing happened. The engine object exists in more renderers
      // than can actually reach a speech service, and a silent failure here is
      // indistinguishable from a dead button.
      recognition.onerror = (e) => {
        listening = false;
        syncVisualState();
        note("speech recognition error: " + ((e && e.error) || "unknown"));
        const why = {
          "not-allowed": "Microphone access was blocked. Type your question instead.",
          "service-not-allowed": "Speech recognition isn't available in this window. Type your question instead.",
          network: "Speech recognition needs a connection. Type your question instead.",
          "audio-capture": "No microphone found. Type your question instead.",
        };
        if (e && e.error !== "aborted" && e.error !== "no-speech") {
          toast(why[e && e.error] || "Couldn't start the microphone. Type your question instead.");
        }
      };
      recognition.onend = () => { listening = false; syncVisualState(); };
    }

    function toggleMic() {
      if (!recognition) {
        // No dictation on this renderer — the orb is a stop button.
        window.JarvisVoice.stop();
        api().stop_speaking();
        return;
      }
      if (listening) {
        recognition.stop();
        listening = false;
        syncVisualState();
        return;
      }
      // Never listen over the top of the assistant's own voice.
      window.JarvisVoice.stop();
      api().stop_speaking();
      handled = false;
      listening = true;
      syncVisualState();
      try {
        recognition.start();
      } catch (err) {
        // start() throws if a previous session is still closing down.
        listening = false;
        syncVisualState();
        toast("Microphone is still busy — try again in a moment.");
      }
    }

    // What this machine's renderer can actually do, reported once the bridge is
    // live (see start()), so "the orb doesn't listen" is diagnosable from the
    // log file without devtools.
    capabilityNote = "speech recognition " + (recognition ? "available" : "NOT available") +
      "; microphone API " +
      (navigator.mediaDevices && navigator.mediaDevices.getUserMedia ? "present" : "absent");

    const micTitle = recognition ? "Tap to speak" : "Stop speaking";
    $("miniOrb").title = micTitle;
    $("miniOrb").addEventListener("click", toggleMic);
    // The hero orb's canvas fills its row, so the whole empty middle of the
    // screen is the tap target — same as the `fill` orb in the Toast build.
    const heroOrb = $("heroOrb").parentElement;
    heroOrb.title = micTitle;
    heroOrb.classList.toggle("is-tappable", true);
    heroOrb.addEventListener("click", toggleMic);
    $("heroHint").textContent = recognition
      ? "Tap the orb and ask, or pick a question from More asks."
      : "Ask about anything in your folder, or pick a question from More asks.";

    $("quickBtn").addEventListener("click", (e) => {
      e.stopPropagation();
      toggleQuickMenu();
    });
    $("quickMenu").addEventListener("click", (e) => e.stopPropagation());
    document.addEventListener("click", () => closeQuickMenu());

    $("guideBtn").addEventListener("click", () => startGuide());
    $("guideSkip").addEventListener("click", () => window.JarvisGuide.skip());
    // Escape is the reflex for "get this off my screen"; the guide is optional,
    // so it must honour it.
    document.addEventListener("keydown", (e) => {
      if (e.key !== "Escape") return;
      if (!$("quickMenu").hidden) closeQuickMenu();
      if (window.JarvisGuide.running) window.JarvisGuide.skip();
    });

    $("muteBtn").addEventListener("click", async () => {
      muted = !muted;
      $("muteBtn").classList.toggle("is-off", muted);
      if (muted) window.JarvisVoice.stop();
      renderState((await api().save_settings({ speak_replies: !muted })).state);
    });

    $("pickFolder").addEventListener("click", async () => {
      const result = await api().pick_folder();
      toast(result.message || "");
      if (result.state) renderState(result.state);
      loadActivity();
    });

    $("toggleWatch").addEventListener("click", async () => {
      const running = state && state.watch && state.watch.running;
      const result = running ? await api().stop_watch() : await api().start_watch();
      toast(result.message || (running ? "Paused." : "Watching."));
      renderState(result.state);
    });

    $("organizeNow").addEventListener("click", async () => {
      const result = await api().organize_now();
      toast(result.message || "");
    });

    $("reindex").addEventListener("click", async () => {
      const result = await api().reindex();
      toast(result.message || "");
    });

    $("saveKey").addEventListener("click", async () => {
      const key = $("apiKey").value.trim();
      if (!key) return;
      $("keyStatus").textContent = "Checking the key…";
      $("keyStatus").className = "hint";
      const result = await api().set_api_key(key);
      $("keyStatus").textContent = result.message || "";
      $("keyStatus").className = "hint " + (result.ok ? "is-ok" : "is-bad");
      if (result.ok) $("apiKey").value = "";
      renderState(result.state);
    });

    $("clearKey").addEventListener("click", async () => {
      renderState((await api().clear_api_key()).state);
      toast("Key removed.");
    });

    $("openData").addEventListener("click", () => api().open_log());

    ["autoOrganize:auto_organize", "recursive:recursive",
     "indexExisting:index_existing", "speakReplies:speak_replies"]
      .forEach((pair) => {
        const [id, key] = pair.split(":");
        $(id).addEventListener("change", async () => {
          const patch = {};
          patch[key] = $(id).checked;
          renderState((await api().save_settings(patch)).state);
        });
      });

    $("voicePicker").addEventListener("change", async () => {
      renderState((await api().save_settings({ voice: $("voicePicker").value })).state);
      // Choosing a voice you can't hear is guesswork — say something in it now.
      window.JarvisVoice.speak("Hello, I'm Jarvis. This is how I'll sound.");
    });
    $("voicePreview").addEventListener("click", () => {
      window.JarvisVoice.speak(
        "Hello, I'm Jarvis. I've filed three new documents for you this morning.");
    });
    $("naturalVoice").addEventListener("change", async () => {
      renderState((await api().save_settings({ natural_voice: $("naturalVoice").checked })).state);
    });

    $("confidence").addEventListener("input", () => {
      $("confidenceValue").textContent = Number($("confidence").value).toFixed(2);
    });
    $("confidence").addEventListener("change", async () => {
      renderState((await api().save_settings({ min_confidence: $("confidence").value })).state);
    });

    $("categories").addEventListener("change", async () => {
      renderState((await api().save_settings({ categories: $("categories").value })).state);
      toast("Categories updated.");
    });

    let searchTimer = 0;
    $("fileSearch").addEventListener("input", () => {
      clearTimeout(searchTimer);
      searchTimer = setTimeout(runSearch, 260);
    });
  }

  async function runSearch() {
    const q = $("fileSearch").value.trim();
    const box = $("fileResults");
    if (!q) {
      box.innerHTML = "";
      box.appendChild(el("div", "empty-note", "Search the contents of every indexed document."));
      return;
    }
    const hits = (await api().search(q, 25)) || [];
    box.innerHTML = "";
    if (!hits.length) {
      box.appendChild(el("div", "empty-note", "No matches."));
      return;
    }
    hits.forEach((hit) => {
      box.appendChild(activityItem({
        kind: "indexed", path: hit.path, name: hit.name,
        category: hit.category, note: hit.snippet, ts: hit.mtime,
      }));
    });
  }

  // ---------------------------------------------------------------- boot

  function startGuide() {
    // The walkthrough narrates itself, so anything already being spoken has to
    // stop first or the two voices overlap.
    api().stop_speaking();
    const wasMuted = muted;
    window.JarvisGuide.start({
      onDone: () => {
        // Muting is about ANSWERS, not the tour — restore whatever the user had.
        if (wasMuted) api().stop_speaking();
        refreshStats();
      },
    });
  }

  let started = false;

  function start() {
    // pywebviewready can arrive after the ready-check below has already run;
    // both paths lead here, and the app must be built exactly once.
    if (started) return;
    // Refuse to build against a half-injected bridge; the poll below will call
    // again once the methods are really there.
    if (!bridgeReady()) return;
    started = true;
    // Wiring the controls must never cost us the boot call: an exception in
    // here used to leave the page looking alive with Python never contacted.
    try {
      wire();
      syncVisualState();
    } catch (err) {
      fatal((err && err.message) || String(err));
    }
    api().boot().then((s) => {
      renderState(s);
      loadActivity();
      note(capabilityNote);
      // First launch only. `guide_seen` is written when the tour finishes OR is
      // skipped, so a user who skips is never shown it again uninvited — the
      // help button in the header replays it on demand.
      if (s && s.config && !s.config.guide_seen) {
        setTimeout(startGuide, 700);
      }
    }, (err) => {
      fatal("the backend did not answer (" + ((err && err.message) || err) + ")");
    });
  }

  /* Is the bridge REALLY usable?
   *
   * Testing `window.pywebview.api` is not enough, and that was the bug behind
   * the window that came up looking alive and did nothing: pywebview injects
   * `window.pywebview = { api: {} }` first and only fills the methods in
   * afterwards, so between those two moments the object is truthy and empty.
   * Anything that starts in that gap dies on `api(...).boot is not a function`,
   * taking the whole script — and every event handler in it — with it.
   */
  const bridgeReady = () =>
    !!(window.pywebview && window.pywebview.api &&
       typeof window.pywebview.api.boot === "function");

  if (bridgeReady()) start();
  else window.addEventListener("pywebviewready", start);

  // Belt and braces for the event never arriving: keep checking for the real
  // method, and if it never turns up, say so rather than presenting a window
  // that looks like the app and answers nothing.
  let waited = 0;
  const readyPoll = setInterval(() => {
    if (started) { clearInterval(readyPoll); return; }
    if (bridgeReady()) {
      clearInterval(readyPoll);
      start();
    } else if ((waited += 250) >= 20000) {
      clearInterval(readyPoll);
      fatal("the page never connected to the app");
    }
  }, 250);
})();
